const BM_HELP_ID=Object.fromEntries(Object.entries(BM_HELP).map(([n,m])=>[exSlug(n),m]));
/* an exercise's profile: {muscle: share}, the main muscle at 1 */
function bmProfile(ex,part){
  const p={},m=typeof exMuscle==='function'?exMuscle(ex,part):'unassigned';
  if(m&&m!=='unassigned')p[m]=1;
  else if(part==='Legs')Object.assign(p,{quads:.35,hamstrings:.35,glutes:.35,calves:.25});   // no honest single guess: the whole part, faintly
  else if(part&&PART_FALLBACK[part])p[PART_FALLBACK[part]]=1;
  for(const [k,v] of Object.entries(BM_HELP_ID[exIdOf(ex)]||{}))if(!(p[k]>=v))p[k]=v;
  return p;
}
/* muscle levels (0..1) -> what each drawn region shows. The shoulder cap is one shape per
   view, so the side head lights both views a little; the chest is one shape graded top
   (incline) to bottom (decline) -- no dividing lines. */
function bmRegions(L){
  const g=k=>L[k]||0,uc=g('upper-chest'),c=g('chest'),lc=g('lower-chest');
  return {chest:[Math.max(uc,c*.85,lc*.2),Math.max(uc*.6,c,lc*.6),Math.max(uc*.2,c*.85,lc)],
    delt:Math.max(g('front-delts'),g('side-delts')*.75),rdelt:Math.max(g('rear-delts'),g('side-delts')*.75),
    traps:g('upper-back'),lats:g('lats'),lowback:g('lower-back'),biceps:g('biceps'),triceps:g('triceps'),
    abs:g('abs'),obliques:g('obliques'),quads:g('quads'),hams:g('hamstrings'),glutes:g('glutes'),calves:g('calves'),adductors:g('adductors')};
}
const BM_FADE=[1,.74,.55,.41,.3,.21];   // today .. 5 days; six or more shows nothing
const bmFig=()=>DB.settings?.sex==='f'?'f':'m';
const bmISO=d=>{const t=new Date(todayISO+'T00:00');t.setDate(t.getDate()-d);return t.toLocaleDateString('en-CA');};
function bmRows(iso){
  return iso===todayISO?((DB.days[iso]||{}).w||[]).map(s=>[s.part,s.ex,s.w,s.reps||[]]):(SEED.sessions?.[iso]||[]);
}
/* the last six days, read once: per muscle the days since it was last worked; per body part
   its latest day, that day's sets and exercises (by the set's main muscle, as everywhere) */
function bmRecency(){
  const since={},parts={};
  for(let d=0;d<BM_FADE.length;d++){
    const iso=bmISO(d),dose={};
    for(const r of bmRows(iso)){
      if(r[1]==='Run'||!(r[3]||[]).length)continue;
      const n=r[3].length,p=bmProfile(r[1],r[0]);
      for(const [m,v] of Object.entries(p))dose[m]=(dose[m]||0)+v*n;
      const m=typeof exMuscle==='function'?exMuscle(r[1],r[0]):'unassigned',vis=MUSCLE_PART[m]||r[0];
      if(!vis||vis==='Run')continue;
      const pt=parts[vis]||(parts[vis]={d,sets:0,ex:[]});
      if(pt.d!==d)continue;
      pt.sets+=n;if(!pt.ex.includes(r[1]))pt.ex.push(r[1]);
    }
    for(const [m,v] of Object.entries(dose))if(v>=1&&since[m]==null)since[m]=d;
  }
  return {since,parts};
}
let _bmFocus=null;   // {part, i} while an exercise's emphasis is open
const bmPct=v=>Math.round(v*100)/100;
function bmFigSVG(key,R,label){
  const F=BM_FIGS[key];if(!F)return '';
  const uid='bm'+key.replace(/\W/g,'')+(++bmFigSVG.n);
  const ch=F.r.chest,stops=R.chest;
  const op=v=>bmPct(v*.92);
  const paths=Object.entries(F.r).map(([k,p])=>{
    if(k==='chest'){if(!Math.max(...stops))return '';return `<path d="${p.d}" fill="url(#${uid})"/>`;}
    const v=R[k]||0;return v>0?`<path d="${p.d}" style="fill:var(--bm-ink);fill-opacity:${op(v)}"/>`:'';
  }).join('');
  const grad=ch?`<defs><linearGradient id="${uid}" gradientUnits="userSpaceOnUse" x1="0" y1="${ch.y0}" x2="0" y2="${ch.y1}">${stops.map((s,i)=>`<stop offset="${i/2}" style="stop-color:var(--bm-ink);stop-opacity:${op(s)}"/>`).join('')}</linearGradient></defs>`:'';
  return `<figure class="bm-view"><svg class="bm-fig" viewBox="0 0 ${F.w} ${F.h}" role="img" aria-label="${label}">${grad}<image href="assets/bodymap/${key}.webp" width="${F.w}" height="${F.h}"/>${paths}</svg><figcaption>${label}</figcaption></figure>`;
}
bmFigSVG.n=0;
const bmAgo=d=>d===0?'Today':d===1?'Yesterday':`${d} days ago`;
/* the words for what an exercise leans on, from its own profile */
function bmLean(p){
  const top=Object.entries(p).sort((a,b)=>b[1]-a[1])[0];if(!top)return 'Muscle not set';
  const nm={'upper-chest':'Upper-chest','lower-chest':'Lower-chest',chest:'Mid-chest','front-delts':'Front-delt','side-delts':'Side-delt','rear-delts':'Rear-delt','upper-back':'Upper-back','lower-back':'Lower-back'}[top[0]];
  return (nm||top[0][0].toUpperCase()+top[0].slice(1))+' emphasis';
}
function bodyMapCard(){
  const fig=bmFig(),{since,parts}=bmRecency();
  if(_bmFocus&&!parts[_bmFocus.part])_bmFocus=null;
  if(_bmFocus){
    const pt=parts[_bmFocus.part],i=Math.min(_bmFocus.i,pt.ex.length-1),ex=pt.ex[i];
    const row=bmRows(bmISO(pt.d)).find(r=>r[1]===ex),p=bmProfile(ex,row?row[0]:_bmFocus.part),R=bmRegions(p);
    const chips=pt.ex.length>1?`<div class="bm-chips" role="group" aria-label="${hesc(partLabel(_bmFocus.part))} exercises">${pt.ex.map((x,j)=>`<button type="button" data-bm-ex="${j}" aria-pressed="${j===i}">${hesc(x)}</button>`).join('')}</div>`:`<div class="bm-exname">${hesc(ex)}</div>`;
    return `<div class="bm-focus">${chips}
      <div class="bm-figs">${bmFigSVG(fig+'-front',R,'Front')}${bmFigSVG(fig+'-back',R,'Back')}</div>
      <div class="bm-legend bm-legend-em"><i class="bm-bar"></i><div class="bm-ends"><span>Less emphasis</span><span>More emphasis</span></div><p class="bm-note">Estimated emphasis · Varies with technique</p></div>
      <div class="bm-lean"><strong>${bmLean(p)}</strong><span>Illustrative exercise profile</span></div>
      <button type="button" class="linkbtn bm-back" data-bm-back>Back to body map</button></div>`;
  }
  const L={};for(const [m,d] of Object.entries(since))L[m]=BM_FADE[d]||0;
  const R=bmRegions(L);
  const order=Object.entries(parts).sort((a,b)=>a[1].d-b[1].d||b[1].sets-a[1].sets);
  const list=order.length?order.map(([v,pt])=>`<button type="button" class="bm-row" data-bm-part="${hesc(v)}"><span><strong>${hesc(partLabel(v))}</strong><small>${bmAgo(pt.d)} · ${pt.sets} set${pt.sets===1?'':'s'}</small></span>${icon('chevron',14)}</button>`).join('')
    :'<p class="bm-empty">Nothing logged in the last six days. Each muscle lights up the day it works.</p>';
  const ticks=['Today','1d','2d','3d','4d','5d','6d+'];
  return `<div class="bm-figs">${bmFigSVG(fig+'-front',R,'Front')}${bmFigSVG(fig+'-back',R,'Back')}</div>
    <div class="bm-legend"><i class="bm-bar bm-bar-days"></i><div class="bm-ticks">${ticks.map(t=>`<span>${t}</span>`).join('')}</div><p class="bm-note">Days since last trained</p></div>
    <div class="bm-list">${list}</div>`;
}
function bmRefresh(){const c=document.querySelector('.bmcard');if(c)c.innerHTML=bodyMapCard();else if(typeof render==='function')render();}
document.addEventListener('click',e=>{
  const t=e.target.closest&&e.target.closest('[data-bm-part],[data-bm-ex],[data-bm-back]');if(!t)return;
  if(t.dataset.bmPart!=null)_bmFocus={part:t.dataset.bmPart,i:0};
  else if(t.dataset.bmEx!=null&&_bmFocus)_bmFocus.i=+t.dataset.bmEx;
  else _bmFocus=null;
  bmRefresh();
});
